<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3'; import { computed } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
type Line={id:string;presentation:string;unit:string;ordered_quantity:string;received_quantity:string;remaining_quantity:string}; type Purchase={id:string;document_number:string;supplier:string;lines:Line[]}; const props=defineProps<{purchase:Purchase;now:string}>();
const form=useForm({received_at:props.now,notes:'',authorization_request_id:'',lines:props.purchase.lines.map(line=>({purchase_line_id:line.id,quantity:Number(line.remaining_quantity)}))}); const selected=computed(()=>form.lines.filter(line=>Number(line.quantity)>0)); const submit=()=>form.transform(data=>({...data,lines:selected.value})).post(`/purchasing/purchases/${props.purchase.id}/receipts`);
</script>
<template><Head title="Registrar recepción" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><p class="text-sm text-muted-foreground">{{ purchase.document_number }} · {{ purchase.supplier }}</p><h1 class="text-2xl font-semibold">Registrar recepción</h1><p class="text-sm text-muted-foreground">Solo las cantidades confirmadas entrarán al inventario.</p></header><form class="grid gap-5" @submit.prevent="submit"><section class="max-w-sm grid gap-2"><Label>Fecha y hora</Label><Input v-model="form.received_at" type="datetime-local" required /></section><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Artículo</th><th class="px-4 py-3">Comprado</th><th class="px-4 py-3">Recibido antes</th><th class="px-4 py-3">Recibir ahora</th></tr></thead><tbody class="divide-y"><tr v-for="(line,index) in purchase.lines" :key="line.id"><td class="px-4 py-3 font-medium">{{ line.presentation }}</td><td class="px-4 py-3">{{ line.ordered_quantity }} {{ line.unit }}</td><td class="px-4 py-3">{{ line.received_quantity }} {{ line.unit }}</td><td class="px-4 py-3"><Input v-model.number="form.lines[index].quantity" class="w-40" type="number" min="0" :max="line.remaining_quantity" step="0.000001" /></td></tr></tbody></table><p v-if="purchase.lines.length===0" class="p-8 text-center text-sm text-muted-foreground">La compra ya fue recibida completamente.</p></section><div class="grid gap-2"><Label>Notas de recepción</Label><textarea v-model="form.notes" rows="3" class="rounded-md border bg-transparent px-3 py-2 text-sm" /></div><p v-if="form.errors.lines" class="text-sm text-destructive">{{ form.errors.lines }}</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link :href="`/purchasing/purchases/${purchase.id}`">Cancelar</Link></Button><Button type="submit" :disabled="form.processing||selected.length===0">Confirmar entrada</Button></div></form></main></template>
